function fireFileInputFromImg(){$("#uploader-image").click()}function readURL(e){if(e.files&&e.files[0]){var a=new FileReader;a.onload=function(e){$("#uploader-image-container").css("background-image","url("+e.target.result+")")},a.readAsDataURL(e.files[0])}}$(document).ready(function(){$("#uploader-image").change(function(){readURL(this),$("#file-name-to-upload").val($(this).val().replace(/C:\\fakepath\\/i,"")),$("#image-to-upload-url").val("")})});